"""Migrated Meridian CRM account validation rules."""

from typing import Any


def _value(record: dict | None, key: str) -> Any:
    if not record:
        return ""
    value = record.get(key, "")
    return "" if value is None else value


def _number(value: Any) -> float:
    if value is None or value == "":
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def _nvl(value: Any, default: Any) -> Any:
    return default if value is None or value == "" else value


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an ACCT_MASTER post-write image against migrated VRL rules."""
    del today  # Present for the fixed interface; unused by these rules.

    errors: list[dict] = []
    event = event.upper()
    old_record = old if event == "UPDATE" else None

    def fail(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append({"code": code, "message": message, "severity": severity})

    # ACC-001: WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        if len(str(_value(record, "ACCT_NM"))) < 2:
            fail("E1001", "Account name too short")

    # ACC-002: WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        if _value(record, "ACCT_TYP") not in ("C", "P", "R", "X"):
            fail("E1002", "Invalid account type")

    # ACC-003: WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        if _number(_nvl(_value(record, "ANN_REV"), 0)) < 0:
            fail("E1003", "Annual revenue negative")

    # ACC-004: WHEN UPDATE
    if event == "UPDATE":
        releasing_zero_limit = (
            _value(old_record, "CRED_HOLD") == "Y"
            and _value(record, "CRED_HOLD") == "N"
            and _number(_value(record, "CRED_LIMIT")) <= 0
        )
        if releasing_zero_limit:
            fail("E1004", "Cannot release credit hold with zero credit limit")

    # ACC-005: WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        if len(str(_value(record, "REGION_CD"))) != 3:
            fail("E1005", "Region code must be 3 chars", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
